INSERT INTO `question` (`id`, `bank_id`, `type`, `stem`, `options`, `answer`, `analysis`, `difficulty`, `sort_no`, `created_at`) VALUES (1,1,'single','若某线性表最常用的操作是存取任一指定序号的元素和在表尾进行插入、删除，则采用（ ）存储方式最节省时间。','[{\"key\": \"A\", \"text\": \"顺序表\"}, {\"key\": \"B\", \"text\": \"双链表\"}, {\"key\": \"C\", \"text\": \"带头结点的双循环链表\"}, {\"key\": \"D\", \"text\": \"单循环链表\"}]','\"A\"',NULL,1,1,'2026-11-01 17:30:17'),(2,1,'single','一个栈的入栈序列为 1,2,3,4,5，则不可能的出栈序列是（ ）。','[{\"key\": \"A\", \"text\": \"2,3,4,1,5\"}, {\"key\": \"B\", \"text\": \"5,4,3,2,1\"}, {\"key\": \"C\", \"text\": \"3,1,4,2,5\"}, {\"key\": \"D\", \"text\": \"1,2,3,4,5\"}]','\"C\"',NULL,1,2,'2026-11-01 17:30:17'),(3,1,'single','循环队列存于数组 A[0..m-1]，front 指向队头元素，rear 指向队尾元素的下一个位置，则队列中元素个数为（ ）。','[{\"key\": \"A\", \"text\": \"(rear-front+m)%m\"}, {\"key\": \"B\", \"text\": \"rear-front+1\"}, {\"key\": \"C\", \"text\": \"rear-front-1\"}, {\"key\": \"D\", \"text\": \"rear-front\"}]','\"A\"',NULL,1,3,'2026-11-01 17:30:17'),(4,1,'single','一棵完全二叉树有 768 个结点，则该树的叶结点个数为（ ）。','[{\"key\": \"A\", \"text\": \"257\"}, {\"key\": \"B\", \"text\": \"258\"}, {\"key\": \"C\", \"text\": \"384\"}, {\"key\": \"D\", \"text\": \"385\"}]','\"C\"',NULL,1,4,'2026-11-01 17:30:17'),(5,1,'single','已知二叉树的先序序列为 ABDECF，中序序列为 DBEAFC，则其后序序列为（ ）。','[{\"key\": \"A\", \"text\": \"DEBFCA\"}, {\"key\": \"B\", \"text\": \"DBEFCA\"}, {\"key\": \"C\", \"text\": \"DEFBCA\"}, {\"key\": \"D\", \"text\": \"EDBFCA\"}]','\"A\"',NULL,1,5,'2026-11-01 17:30:17'),(6,1,'single','具有 n 个顶点的无向连通图至少有（ ）条边。','[{\"key\": \"A\", \"text\": \"n\"}, {\"key\": \"B\", \"text\": \"n-1\"}, {\"key\": \"C\", \"text\": \"n+1\"}, {\"key\": \"D\", \"text\": \"n(n-1)/2\"}]','\"B\"',NULL,1,6,'2026-11-01 17:30:17'),(7,1,'single','对 n 个元素进行快速排序，最坏情况下的时间复杂度为（ ）。','[{\"key\": \"A\", \"text\": \"O(n)\"}, {\"key\": \"B\", \"text\": \"O(nlog₂n)\"}, {\"key\": \"C\", \"text\": \"O(n²)\"}, {\"key\": \"D\", \"text\": \"O(log₂n)\"}]','\"C\"',NULL,1,7,'2026-11-01 17:30:17'),(8,1,'single','下列排序算法中，不稳定的是（ ）。','[{\"key\": \"A\", \"text\": \"直接插入排序\"}, {\"key\": \"B\", \"text\": \"冒泡排序\"}, {\"key\": \"C\", \"text\": \"归并排序\"}, {\"key\": \"D\", \"text\": \"堆排序\"}]','\"D\"',NULL,1,8,'2026-11-01 17:30:17'),(9,1,'single','在有序表 {2,5,8,11,15,18,21,25,30} 中折半查找 11（下标从 1 开始，mid=⌊(low+high)/2⌋），需要比较的次数为（ ）。','[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"3\"}, {\"key\": \"C\", \"text\": \"4\"}, {\"key\": \"D\", \"text\": \"5\"}]','\"C\"',NULL,1,9,'2026-11-01 17:30:17'),(10,1,'single','用邻接表存储有 n 个顶点、e 条边的图，深度优先遍历的时间复杂度为（ ）。','[{\"key\": \"A\", \"text\": \"O(n)\"}, {\"key\": \"B\", \"text\": \"O(e)\"}, {\"key\": \"C\", \"text\": \"O(n+e)\"}, {\"key\": \"D\", \"text\": \"O(n²)\"}]','\"C\"',NULL,1,10,'2026-11-01 17:30:17'),(11,1,'single','一棵哈夫曼树有 n 个叶结点，则该树的结点总数为（ ）。','[{\"key\": \"A\", \"text\": \"2n\"}, {\"key\": \"B\", \"text\": \"2n-1\"}, {\"key\": \"C\", \"text\": \"2n+1\"}, {\"key\": \"D\", \"text\": \"n+1\"}]','\"B\"',NULL,1,11,'2026-11-01 17:30:17'),(12,1,'single','模式串 \"abaabc\" 的 next 数组（next[1]=0）为（ ）。','[{\"key\": \"A\", \"text\": \"0 1 1 2 2 3\"}, {\"key\": \"B\", \"text\": \"0 1 0 2 1 2\"}, {\"key\": \"C\", \"text\": \"0 1 1 2 2 2\"}, {\"key\": \"D\", \"text\": \"0 1 2 2 2 3\"}]','\"A\"',NULL,1,12,'2026-11-01 17:30:17'),(13,1,'multi','下列关于 m 阶 B 树的说法中，正确的有（ ）。','[{\"key\": \"A\", \"text\": \"每个结点至多有 m 棵子树\"}, {\"key\": \"B\", \"text\": \"所有叶结点都在同一层\"}, {\"key\": \"C\", \"text\": \"若根结点不是终端结点，则至少有两棵子树\"}, {\"key\": \"D\", \"text\": \"叶结点之间用指针链接，支持顺序扫描\"}, {\"key\": \"E\", \"text\": \"除根以外的非叶结点至少有 ⌈m/2⌉ 棵子树\"}]','[\"A\", \"B\", \"C\", \"E\"]',NULL,1,13,'2026-11-01 17:30:17'),(14,1,'multi','下列排序算法中，平均时间复杂度为 O(nlog₂n) 的有（ ）。','[{\"key\": \"A\", \"text\": \"快速排序\"}, {\"key\": \"B\", \"text\": \"堆排序\"}, {\"key\": \"C\", \"text\": \"归并排序\"}, {\"key\": \"D\", \"text\": \"简单选择排序\"}]','[\"A\", \"B\", \"C\"]',NULL,1,14,'2026-11-01 17:30:17'),(15,1,'multi','下列关于拓扑排序的说法中，正确的有（ ）。','[{\"key\": \"A\", \"text\": \"有向无环图一定存在拓扑序列\"}, {\"key\": \"B\", \"text\": \"拓扑序列可能不唯一\"}, {\"key\": \"C\", \"text\": \"含有回路的有向图不存在拓扑序列\"}, {\"key\": \"D\", \"text\": \"无向图也可以进行拓扑排序\"}]','[\"A\", \"B\", \"C\"]',NULL,1,15,'2026-11-01 17:30:17'),(16,1,'multi','下列数据结构中，属于线性结构的有（ ）。','[{\"key\": \"A\", \"text\": \"栈\"}, {\"key\": \"B\", \"text\": \"队列\"}, {\"key\": \"C\", \"text\": \"二叉树\"}, {\"key\": \"D\", \"text\": \"串\"}, {\"key\": \"E\", \"text\": \"图\"}]','[\"A\", \"B\", \"D\"]',NULL,1,16,'2026-11-01 17:30:17'),(17,1,'judge','线性表的顺序存储结构是一种随机存取的存储结构。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"A\"',NULL,1,17,'2026-11-01 17:30:17'),(18,1,'judge','对二叉排序树进行后序遍历，得到的序列是有序的。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"B\"',NULL,1,18,'2026-11-01 17:30:17'),(19,1,'judge','含 n 个顶点的无向完全图有 n(n-1)/2 条边。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"A\"',NULL,1,19,'2026-11-01 17:30:17'),(20,1,'judge','Dijkstra 算法适用于含负权边的图求单源最短路径。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"B\"',NULL,1,20,'2026-11-01 17:30:17'),(21,1,'single','某机字长 8 位，采用补码表示整数，则能表示的范围是（ ）。','[{\"key\": \"A\", \"text\": \"-128～127\"}, {\"key\": \"B\", \"text\": \"-127～127\"}, {\"key\": \"C\", \"text\": \"-128～128\"}, {\"key\": \"D\", \"text\": \"-127～128\"}]','\"A\"',NULL,1,1,'2026-11-01 17:30:17'),(22,1,'single','十进制数 -1 的 8 位补码是（ ）。','[{\"key\": \"A\", \"text\": \"10000001\"}, {\"key\": \"B\", \"text\": \"11111110\"}, {\"key\": \"C\", \"text\": \"11111111\"}, {\"key\": \"D\", \"text\": \"01111111\"}]','\"C\"',NULL,1,2,'2026-11-01 17:30:17'),(23,1,'single','IEEE 754 单精度浮点数的阶码偏置值为（ ）。','[{\"key\": \"A\", \"text\": \"127\"}, {\"key\": \"B\", \"text\": \"128\"}, {\"key\": \"C\", \"text\": \"1023\"}, {\"key\": \"D\", \"text\": \"1024\"}]','\"A\"',NULL,1,3,'2026-11-01 17:30:17'),(24,1,'single','下列存储部件中，存取速度最快的是（ ）。','[{\"key\": \"A\", \"text\": \"主存\"}, {\"key\": \"B\", \"text\": \"Cache\"}, {\"key\": \"C\", \"text\": \"寄存器\"}, {\"key\": \"D\", \"text\": \"磁盘\"}]','\"C\"',NULL,1,4,'2026-11-01 17:30:17'),(25,1,'single','某 Cache 共 64 行，主存块大小 16B，采用直接映射，按字节编址。主存地址 1234H 映射到的 Cache 行号是（ ）。','[{\"key\": \"A\", \"text\": \"35\"}, {\"key\": \"B\", \"text\": \"34\"}, {\"key\": \"C\", \"text\": \"18\"}, {\"key\": \"D\", \"text\": \"291\"}]','\"A\"',NULL,1,5,'2026-11-01 17:30:17'),(26,1,'single','程序计数器 PC 中存放的是（ ）。','[{\"key\": \"A\", \"text\": \"当前正在执行的指令\"}, {\"key\": \"B\", \"text\": \"下一条要执行的指令的地址\"}, {\"key\": \"C\", \"text\": \"运算结果\"}, {\"key\": \"D\", \"text\": \"操作数的地址\"}]','\"B\"',NULL,1,6,'2026-11-01 17:30:17'),(27,1,'single','采用 DMA 方式传送数据时，每传送一个数据要占用（ ）的时间。','[{\"key\": \"A\", \"text\": \"一个指令周期\"}, {\"key\": \"B\", \"text\": \"一个机器周期\"}, {\"key\": \"C\", \"text\": \"一个存储周期\"}, {\"key\": \"D\", \"text\": \"一个时钟周期\"}]','\"C\"',NULL,1,7,'2026-11-01 17:30:17'),(28,1,'single','指令流水线中，因后一条指令要用到前一条指令的结果而引起的冲突称为（ ）。','[{\"key\": \"A\", \"text\": \"结构冒险\"}, {\"key\": \"B\", \"text\": \"数据冒险\"}, {\"key\": \"C\", \"text\": \"控制冒险\"}, {\"key\": \"D\", \"text\": \"资源冲突\"}]','\"B\"',NULL,1,8,'2026-11-01 17:30:17'),(29,1,'single','某计算机主频为 2GHz，平均 CPI 为 4，则其 MIPS 为（ ）。','[{\"key\": \"A\", \"text\": \"250\"}, {\"key\": \"B\", \"text\": \"500\"}, {\"key\": \"C\", \"text\": \"800\"}, {\"key\": \"D\", \"text\": \"2000\"}]','\"B\"',NULL,1,9,'2026-11-01 17:30:17'),(30,1,'single','在虚拟存储系统中，快表 TLB 的作用是（ ）。','[{\"key\": \"A\", \"text\": \"加快虚实地址变换\"}, {\"key\": \"B\", \"text\": \"扩大主存容量\"}, {\"key\": \"C\", \"text\": \"存放全部页表\"}, {\"key\": \"D\", \"text\": \"存放 Cache 标记\"}]','\"A\"',NULL,1,10,'2026-11-01 17:30:17'),(31,1,'single','中断响应时由硬件（中断隐指令）完成的操作不包括（ ）。','[{\"key\": \"A\", \"text\": \"关中断\"}, {\"key\": \"B\", \"text\": \"保存断点\"}, {\"key\": \"C\", \"text\": \"送中断服务程序入口地址\"}, {\"key\": \"D\", \"text\": \"保存通用寄存器内容\"}]','\"D\"',NULL,1,11,'2026-11-01 17:30:17'),(32,1,'single','容量为 16K×8 位的存储器，地址线与数据线的总数是（ ）。','[{\"key\": \"A\", \"text\": \"20\"}, {\"key\": \"B\", \"text\": \"22\"}, {\"key\": \"C\", \"text\": \"24\"}, {\"key\": \"D\", \"text\": \"30\"}]','\"B\"',NULL,1,12,'2026-11-01 17:30:17'),(33,1,'multi','下列属于 RISC 特点的有（ ）。','[{\"key\": \"A\", \"text\": \"指令长度固定\"}, {\"key\": \"B\", \"text\": \"寻址方式少\"}, {\"key\": \"C\", \"text\": \"大多数指令在一个周期内完成\"}, {\"key\": \"D\", \"text\": \"以微程序控制为主\"}, {\"key\": \"E\", \"text\": \"通用寄存器数量较多\"}]','[\"A\", \"B\", \"C\", \"E\"]',NULL,1,13,'2026-11-01 17:30:17'),(34,1,'multi','下列关于 Cache 的说法中，正确的有（ ）。','[{\"key\": \"A\", \"text\": \"Cache 对程序员透明\"}, {\"key\": \"B\", \"text\": \"全相联映射的块冲突概率最低\"}, {\"key\": \"C\", \"text\": \"写回法需要为每行设置脏位\"}, {\"key\": \"D\", \"text\": \"直接映射不需要替换算法\"}, {\"key\": \"E\", \"text\": \"Cache 容量通常大于主存\"}]','[\"A\", \"B\", \"C\", \"D\"]',NULL,1,14,'2026-11-01 17:30:17'),(35,1,'multi','影响指令流水线性能的冒险包括（ ）。','[{\"key\": \"A\", \"text\": \"结构冒险\"}, {\"key\": \"B\", \"text\": \"数据冒险\"}, {\"key\": \"C\", \"text\": \"控制冒险\"}, {\"key\": \"D\", \"text\": \"缓存冒险\"}]','[\"A\", \"B\", \"C\"]',NULL,1,15,'2026-11-01 17:30:17'),(36,1,'multi','下列寻址方式中，操作数位于主存的有（ ）。','[{\"key\": \"A\", \"text\": \"立即寻址\"}, {\"key\": \"B\", \"text\": \"直接寻址\"}, {\"key\": \"C\", \"text\": \"寄存器间接寻址\"}, {\"key\": \"D\", \"text\": \"寄存器寻址\"}, {\"key\": \"E\", \"text\": \"间接寻址\"}]','[\"B\", \"C\", \"E\"]',NULL,1,16,'2026-11-01 17:30:17'),(37,1,'judge','定点整数采用补码表示时，0 的表示是唯一的。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"A\"',NULL,1,17,'2026-11-01 17:30:17'),(38,1,'judge','DRAM 需要定期刷新，SRAM 不需要刷新。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"A\"',NULL,1,18,'2026-11-01 17:30:17'),(39,1,'judge','微程序控制器的速度比硬布线控制器快。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"B\"',NULL,1,19,'2026-11-01 17:30:17'),(40,1,'judge','指令寄存器 IR 中存放的是下一条指令的地址。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"B\"',NULL,1,20,'2026-11-01 17:30:17'),(41,2,'single','进程由运行态转为就绪态，可能的原因是（ ）。','[{\"key\": \"A\", \"text\": \"等待 I/O\"}, {\"key\": \"B\", \"text\": \"时间片用完\"}, {\"key\": \"C\", \"text\": \"I/O 完成\"}, {\"key\": \"D\", \"text\": \"进程刚被创建\"}]','\"B\"',NULL,1,1,'2026-11-01 17:30:17'),(42,2,'single','单处理机系统中有 n 个进程，某时刻有进程在运行，则处于就绪态的进程最多有（ ）个。','[{\"key\": \"A\", \"text\": \"n\"}, {\"key\": \"B\", \"text\": \"n-1\"}, {\"key\": \"C\", \"text\": \"n+1\"}, {\"key\": \"D\", \"text\": \"1\"}]','\"B\"',NULL,1,2,'2026-11-01 17:30:17'),(43,2,'single','下列进程调度算法中，可能导致长作业\"饥饿\"的是（ ）。','[{\"key\": \"A\", \"text\": \"先来先服务\"}, {\"key\": \"B\", \"text\": \"时间片轮转\"}, {\"key\": \"C\", \"text\": \"短作业优先\"}, {\"key\": \"D\", \"text\": \"高响应比优先\"}]','\"C\"',NULL,1,3,'2026-11-01 17:30:17'),(44,2,'single','系统中有 3 个进程，每个进程最多需要 2 台同类打印机，则系统至少配置（ ）台打印机才不会发生死锁。','[{\"key\": \"A\", \"text\": \"3\"}, {\"key\": \"B\", \"text\": \"4\"}, {\"key\": \"C\", \"text\": \"5\"}, {\"key\": \"D\", \"text\": \"6\"}]','\"B\"',NULL,1,4,'2026-11-01 17:30:17'),(45,2,'single','下列不属于产生死锁的必要条件的是（ ）。','[{\"key\": \"A\", \"text\": \"互斥\"}, {\"key\": \"B\", \"text\": \"请求和保持\"}, {\"key\": \"C\", \"text\": \"不可剥夺\"}, {\"key\": \"D\", \"text\": \"进程优先级不同\"}]','\"D\"',NULL,1,5,'2026-11-01 17:30:17'),(46,2,'single','银行家算法是一种（ ）方法。','[{\"key\": \"A\", \"text\": \"死锁预防\"}, {\"key\": \"B\", \"text\": \"死锁避免\"}, {\"key\": \"C\", \"text\": \"死锁检测\"}, {\"key\": \"D\", \"text\": \"死锁解除\"}]','\"B\"',NULL,1,6,'2026-11-01 17:30:17'),(47,2,'single','某页式系统页面大小为 4KB，逻辑地址 3A7FH 所在的页号是（ ）。','[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"3\"}, {\"key\": \"C\", \"text\": \"3AH\"}, {\"key\": \"D\", \"text\": \"7\"}]','\"B\"',NULL,1,7,'2026-11-01 17:30:17'),(48,2,'single','页面引用串为 1,2,3,4,1,2,5,1,2,3,4,5，分配 3 个物理块，采用 FIFO 置换，缺页次数为（ ）。','[{\"key\": \"A\", \"text\": \"8\"}, {\"key\": \"B\", \"text\": \"9\"}, {\"key\": \"C\", \"text\": \"10\"}, {\"key\": \"D\", \"text\": \"12\"}]','\"B\"',NULL,1,8,'2026-11-01 17:30:17'),(49,2,'single','信号量 S 的初值为 3，当前值为 -2，表示有（ ）个进程在等待该资源。','[{\"key\": \"A\", \"text\": \"0\"}, {\"key\": \"B\", \"text\": \"1\"}, {\"key\": \"C\", \"text\": \"2\"}, {\"key\": \"D\", \"text\": \"3\"}]','\"C\"',NULL,1,9,'2026-11-01 17:30:17'),(50,2,'single','下列磁盘调度算法中，可能使某些请求长期得不到服务的是（ ）。','[{\"key\": \"A\", \"text\": \"FCFS\"}, {\"key\": \"B\", \"text\": \"SSTF\"}, {\"key\": \"C\", \"text\": \"SCAN\"}, {\"key\": \"D\", \"text\": \"C-SCAN\"}]','\"B\"',NULL,1,10,'2026-11-01 17:30:17'),(51,2,'single','文件系统中，记录文件属性和存放位置等信息的数据结构是（ ）。','[{\"key\": \"A\", \"text\": \"文件控制块 FCB\"}, {\"key\": \"B\", \"text\": \"进程控制块 PCB\"}, {\"key\": \"C\", \"text\": \"页表\"}, {\"key\": \"D\", \"text\": \"位示图\"}]','\"A\"',NULL,1,11,'2026-11-01 17:30:17'),(52,2,'single','采用多级反馈队列调度算法时，新创建的进程首先进入（ ）。','[{\"key\": \"A\", \"text\": \"优先级最低的队列\"}, {\"key\": \"B\", \"text\": \"优先级最高的队列\"}, {\"key\": \"C\", \"text\": \"任意一个队列\"}, {\"key\": \"D\", \"text\": \"阻塞队列\"}]','\"B\"',NULL,1,12,'2026-11-01 17:30:17'),(53,2,'multi','下列属于进程间通信方式的有（ ）。','[{\"key\": \"A\", \"text\": \"共享存储\"}, {\"key\": \"B\", \"text\": \"消息传递\"}, {\"key\": \"C\", \"text\": \"管道\"}, {\"key\": \"D\", \"text\": \"中断向量表\"}]','[\"A\", \"B\", \"C\"]',NULL,1,13,'2026-11-01 17:30:17'),(54,2,'multi','下列关于线程的说法中，正确的有（ ）。','[{\"key\": \"A\", \"text\": \"引入线程后，线程是处理机调度的基本单位\"}, {\"key\": \"B\", \"text\": \"同一进程内的线程共享该进程的地址空间\"}, {\"key\": \"C\", \"text\": \"每个线程有自己独立的栈\"}, {\"key\": \"D\", \"text\": \"同一进程内线程切换的开销一般大于进程切换\"}]','[\"A\", \"B\", \"C\"]',NULL,1,14,'2026-11-01 17:30:17'),(55,2,'multi','下列页面置换算法中，能够实际实现的有（ ）。','[{\"key\": \"A\", \"text\": \"OPT 最佳置换\"}, {\"key\": \"B\", \"text\": \"FIFO 先进先出\"}, {\"key\": \"C\", \"text\": \"LRU 最近最久未使用\"}, {\"key\": \"D\", \"text\": \"CLOCK 时钟置换\"}]','[\"B\", \"C\", \"D\"]',NULL,1,15,'2026-11-01 17:30:17'),(56,2,'multi','下列关于虚拟存储器的说法中，正确的有（ ）。','[{\"key\": \"A\", \"text\": \"理论基础是程序的局部性原理\"}, {\"key\": \"B\", \"text\": \"作业只需部分装入内存即可运行\"}, {\"key\": \"C\", \"text\": \"虚存容量受地址结构和外存容量限制\"}, {\"key\": \"D\", \"text\": \"实现虚拟存储不需要硬件支持\"}]','[\"A\", \"B\", \"C\"]',NULL,1,16,'2026-11-01 17:30:17'),(57,2,'judge','临界区是指进程中访问临界资源的那段代码。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"A\"',NULL,1,17,'2026-11-01 17:30:17'),(58,2,'judge','SPOOLing 技术可以把独占设备改造成逻辑上的共享设备。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"A\"',NULL,1,18,'2026-11-01 17:30:17'),(59,2,'judge','分页存储管理会产生外部碎片。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"B\"',NULL,1,19,'2026-11-01 17:30:17'),(60,2,'judge','系统处于不安全状态时一定会发生死锁。','[{\"key\": \"A\", \"text\": \"对\"}, {\"key\": \"B\", \"text\": \"错\"}]','\"B\"',NULL,1,20,'2026-11-01 17:30:17'),(61,2,'single','在 OSI 参考模型中，负责路由选择的是（ ）。','[{\"key\": \"A\", \"text\": \"数据链路层\"}, {\"key\": \"B\", \"text\": \"网络层\"}, {\"key\": \"C\", \"text\": \"传输层\"}, {\"key\": \"D\", \"text\": \"会话层\"}]','\"B\"',NULL,1,1,'2026-11-01 17:30:17'),(62,2,'single','在 TCP/IP 体系结构中，TCP 协议位于（ ）。','[{\"key\": \"A\", \"text\": \"网络接口层\"}, {\"key\": \"B\", \"text\": \"网际层\"}, {\"key\": \"C\", \"text\": \"运输层\"}, {\"key\": \"D\", \"text\": \"应用层\"}]','\"C\"',NULL,1,2,'2026-11-01 17:30:17'),(63,2,'single','子网掩码为 255.255.255.192 的子网，可分配给主机的地址数为（ ）。','[{\"key\": \"A\", \"text\": \"30\"}, {\"key\": \"B\", \"text\": \"62\"}, {\"key\": \"C\", \"text\": \"64\"}, {\"key\": \"D\", \"text\": \"126\"}]','\"B\"',NULL,1,3,'2026-11-01 17:30:17'),(64,2,'single','IP 地址 192.168.10.130/26 所在子网的广播地址是（ ）。','[{\"key\": \"A\", \"text\": \"192.168.10.127\"}, {\"key\": \"B\", \"text\": \"192.168.10.128\"}, {\"key\": \"C\", \"text\": \"192.168.10.191\"}, {\"key\": \"D\", \"text\": \"192.168.10.255\"}]','\"C\"',NULL,1,4,'2026-11-01 17:30:17'),(65,2,'single','传统以太网采用的介质访问控制方法是（ ）。','[{\"key\": \"A\", \"text\": \"CSMA/CA\"}, {\"key\": \"B\", \"text\": \"CSMA/CD\"}, {\"key\": \"C\", \"text\": \"令牌环\"}, {\"key\": \"D\", \"text\": \"时分复用\"}]','\"B\"',NULL,1,5,'2026-11-01 17:30:17'),(66,2,'single','在无噪声信道上，带宽为 4kHz，采用 4 种相位的调制方式，最大数据传输率为（ ）。','[{\"key\": \"A\", \"text\": \"8kb/s\"}, {\"key\": \"B\", \"text\": \"16kb/s\"}, {\"key\": \"C\", \"text\": \"24kb/s\"}, {\"key\": \"D\", \"text\": \"32kb/s\"}]','\"B\"',NULL,1,6,'2026-11-01 17:30:17'),(67,2,'single','TCP 建立连接的过程需要（ ）次握手。','[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"3\"}, {\"key\": \"C\", \"text\": \"4\"}, {\"key\": \"D\", \"text\": \"5\"}]','\"B\"',NULL,1,7,'2026-11-01 17:30:17'),(68,2,'single','TCP 拥塞控制的慢开始阶段，拥塞窗口按（ ）规律增长。','[{\"key\": \"A\", \"text\": \"线性\"}, {\"key\": \"B\", \"text\": \"指数\"}, {\"key\": \"C\", \"text\": \"保持不变\"}, {\"key\": \"D\", \"text\": \"对数\"}]','\"B\"',NULL,1,8,'2026-11-01 17:30:17'),(69,2,'single','DNS 查询通常使用的运输层协议和端口号是（ ）。','[{\"key\": \"A\", \"text\": \"TCP 80\"}, {\"key\": \"B\", \"text\": \"UDP 53\"}, {\"key\": \"C\", \"text\": \"TCP 25\"}, {\"key\": \"D\", \"text\": \"UDP 67\"}]','\"B\"',NULL,1,9,'2026-11-01 17:30:17'),(70,2,'single','ARP 协议的作用是（ ）。','[{\"key\": \"A\", \"text\": \"将 IP 地址解析为 MAC 地址\"}, {\"key\": \"B\", \"text\": \"将 MAC 地址解析为 IP 地址\"}, {\"key\": \"C\", \"text\": \"将域名解析为 IP 地址\"}, {\"key\": \"D\", \"text\": \"为主机动态分配 IP 地址\"}]','\"A\"',NULL,1,10,'2026-11-01 17:30:17'),(71,2,'single','后退 N 帧协议（GBN）中，帧序号用 3 位二进制表示，则发送窗口的最大值为（ ）。','[{\"key\": \"A\", \"text\": \"4\"}, {\"key\": \"B\", \"text\": \"7\"}, {\"key\": \"C\", \"text\": \"8\"}, {\"key\": \"D\", \"text\": \"1\"}]','\"B\"',NULL,1,11,'2026-11-01 17:30:17'),(72,2,'single','HTTP 协议默认使用的端口号是（ ）。','[{\"key\": \"A\", \"text\": \"21\"}, {\"key\": \"B\", \"text\": \"23\"}, {\"key\": \"C\", \"text\": \"80\"}, {\"key\": \"D\", \"text\": \"110\"}]','\"C\"',NULL,1,12,'2026-11-01 17:30:17'),(73,2,'multi','下列应用层协议中，通常基于 UDP 的有（ ）。','[{\"key\": \"A\", \"text\": \"DNS\"}, {\"key\": \"B\", \"text\": \"DHCP\"}, {\"key\": \"C\", \"text\": \"SNMP\"}, {\"key\": \"D\", \"text\": \"FTP\"}, {\"key\": \"E\", \"text\": \"HTTP\"}]','[\"A\", \"B\", \"C\"]',NULL,1,13,'2026-11-01 17:30:17'),(74,2,'multi','下列 IP 地址中，属于私有地址的有（ ）。','[{\"key\": \"A\", \"text\": \"10.1.1.1\"}, {\"key\": \"B\", \"text\": \"172.16.5.5\"}, {\"key\": \"C\", \"text\": \"192.168.0.1\"}, {\"key\": \"D\", \"text\": \"172.32.0.1\"}, {\"key\": \"E\", \"text\": \"11.0.0.